window.products.push({"id":1071871,"name":"Vintage Ski World Garmisch, Germany 1936 IV Winter Olympic Games Official Poster, Image Size 13 x 18 inches","category":"homeandappliances","retail price":29.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/61P3hNwjK9L._AC_SL1000_.jpg","description":"1936 Garmisch Winter Olympics Lodge Decor Poster Attractive vintage reproduction of the official poster of the1936 Winter Olympics, which took place in Garmisch Partenkirchen, Germany. Dick Durrance returned to Germany to ski in this Olympics. He had initially learned to ski here as he attended a German school and became one of the best young ski racers in Europe. He represented the US in the downhill and slalom races. 13 x 18 inch quality reproduction Also check out our Winter Olympics Poster Set!! To view, just enter this title into the Amazon Search bar: 'Set of 20 Official Olympic Winter Games Posters from 1924 - 2006'.","images":["https://m.media-amazon.com/images/I/61P3hNwjK9L._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Vintage Ski World","source_asin":"B002IQ7D2M","category_path":"Home & Kitchen"},"sku":"BM-1071871","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B002IQ7D2M","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B002IQ7D2M","price_pending":true,"merchant_ready":false});
